text:
{
  "name": "About ParCool",
  "description": "This section provide descriptions about this mod's concept and information.",
  "icon": "minecraft:book",
  "sortnum": 0
}

{
  "name": "ParCool Actions",
  "description": "This section provide descriptions about actions added by ParCool. There are tons of different abilities in the Parcool arsenal. let's see how to use them!",
  "icon": "minecraft:feather",
  "sortnum": 1
}

{
  "name": "Other Features",
  "description": "This section provides descriptions about miscellanious parkour features added by Parcool.",
  "icon": "minecraft:iron_hoe",
  "sortnum": 2
}

{
  "name": "What is ParCool?",
  "icon": "minecraft:feather",
  "category": "parcool:category_about",
  "sortnum": 1,
  "pages": [
    {
      "type": "patchouli:text",
      "text": "Thanks for playing this mod!$(br2)This mod is a Minecraft Forge mod for more $(bold)Cool$() actions like $(bold)Parkour$()$(br)Some actions are actually techniques of parkour.$(br2)Now you become a parkour-player. Let's run around the Minecraft World!"
    },
    {
      "type": "patchouli:image",
      "images": [
        "parcool:textures/gui/entries/logo_round.png"
      ]
    }
  ]
}

{
  "name": "What is Parkour?",
  "icon": "minecraft:golden_boots",
  "category": "parcool:category_about",
  "sortnum": 2,
  "pages": [
    {
      "type": "patchouli:text",
      "text": "$(italic)Parkour$() is a kind of sports, organized by $(italic)David Belle$().$(br)Parkour is an activity that humans move to another point quickly as possible by oneself.$(br2)The name comes from $(italic)parcours$() of French, and the players called $(italic)Traceur$().$(br)Sometimes Parkour is called $(italic)Free Running$(). This is said to be a English translation of Parkour."
    }
  ]
}

{
  "name": "Credit",
  "icon": "minecraft:written_book",
  "category": "parcool:category_about",
  "sortnum": 5,
  "pages": [
    {
      "type": "patchouli:text",
      "text": "This is a list of Mod developers and Translators.$(br2)I also appreciate contributions by people not listed."
    },
    {
      "type": "patchouli:text",
      "title": "Mod Developers",
      "text": "Main Development$()$(italic)$(list)alRex-U$()"
    },
    {
      "type": "patchouli:text",
